// Deterministic random source for test generators, the same in Node and browsers.
// `rngFrom(seed)` takes a hex seed and returns helpers; a generator defines
// `generate(seed, n)` and returns n argument arrays.
function rngFrom(seed) {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < seed.length; i++) {
    h ^= seed.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  let a = h ^ 0x9e3779b9;
  const next = () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  const int = (lo, hi) => lo + Math.floor(next() * (hi - lo + 1));
  const pick = (xs) => xs[int(0, xs.length - 1)];
  const chance = (p) => next() < p;
  const shuffle = (xs) => {
    const a2 = xs.slice();
    for (let i = a2.length - 1; i > 0; i--) {
      const j = int(0, i);
      const t = a2[i];
      a2[i] = a2[j];
      a2[j] = t;
    }
    return a2;
  };
  return { next, int, pick, chance, shuffle };
}

function generate(seed, n) {
  const r = rngFrom(seed);
  const ws = () => r.pick(["", "", " ", "  ", "\t", "\n"]);
  const number = () => (r.chance(0.7) ? String(r.int(0, 99)) : `${r.int(0, 20)}.${r.pick(["5", "25", "75", "125", "1"])}`);
  const expr = (d) => {
    if (d <= 0 || r.chance(0.25)) {
      let x = number();
      if (r.chance(0.2)) x = r.pick(["-", "+", "--", "-+"]) + ws() + x;
      return x;
    }
    if (r.chance(0.2)) return "(" + ws() + expr(d - 1) + ws() + ")";
    return expr(d - 1) + ws() + r.pick(["+", "-", "*", "/"]) + ws() + expr(d - 1);
  };
  const bad = [
    () => expr(2) + ws() + r.pick(["+", "*", "/"]),
    () => "(" + expr(2),
    () => expr(2) + ")",
    () => expr(1) + " " + number(),
    () => expr(1) + r.pick(["%", "^", "x", "&"]) + expr(1),
    () => expr(1) + " / (" + number() + " - " + "$" + ")",
    () => r.pick(["1.", ".5", "1..2", "1e3", "()"]),
    () => expr(1) + " / " + r.pick(["0", "(2 - 2)", "0.0", "(1 - 1) * 3"]),
    () => r.pick(["", "   "]),
